[SysClientCacheDataMethodAttribute(true)]
public display str RRBdisplayBookGenre()
{
    FTDBookTable book;

    if (this.RRBBookTable)
    {
        select firstonly Genre from book
            where book.RecId == this.RRBBookTable;
    }

    return enum2Str(book.Genre);
}

[SysClientCacheDataMethodAttribute(true)]
public display FTDGenreEnum RRBdisplayBookGenreCombo()
{
    FTDBookTable book;

    if (this.RRBBookTable)
    {
        select firstonly Genre from book
            where book.RecId == this.RRBBookTable;
    }

    return book.Genre;
}
